import 'package:flutter/material.dart';
import '../../core/api.dart';
import '../../core/theme.dart';
class NotificationsScreen extends StatefulWidget{const NotificationsScreen({super.key});@override State<NotificationsScreen> createState()=>_NotificationsScreenState();}
class _NotificationsScreenState extends State<NotificationsScreen>{List<Map<String,dynamic>> items=[];int unread=0;bool loading=true;Future<void> load()async{try{final d=ApiClient.decode(await ApiClient.get('/notifications')) as Map;setState((){items=((d['notifications'] as List?)??const[]).map((e)=>Map<String,dynamic>.from(e)).toList();unread=(d['unread'] as num?)?.toInt()??0;});}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>loading=false);}}Future<void> markAll()async{await ApiClient.post('/notifications',{'action':'mark_all_read'});await load();}Future<void> mark(String id)async{await ApiClient.post('/notifications',{'action':'mark_read','id':id});await load();}@override void initState(){super.initState();load();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text('Notificaciones${unread>0?' ($unread)':''}'),actions:[TextButton(onPressed:unread==0?null:markAll,child:const Text('Marcar todo'))]),body:RefreshIndicator(onRefresh:load,child:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(14),children:items.isEmpty?[const Center(child:Padding(padding:EdgeInsets.all(40),child:Text('No tienes notificaciones',style:TextStyle(color:AppColors.muted))))]:items.map((n)=>GlassCard(padding:const EdgeInsets.symmetric(horizontal:8,vertical:4),onTap:n['read']==true?null:()=>mark('${n['id']}'),child:ListTile(leading:Icon(n['read']==true?Icons.notifications_none:Icons.notifications_active,color:n['read']==true?AppColors.muted:AppColors.cyan),title:Text('${n['title']??''}'),subtitle:Text('${n['message']??''}',style:const TextStyle(color:AppColors.muted)),trailing:n['read']==true?null:const Icon(Icons.circle,size:8,color:AppColors.cyan)))).toList())));
}
